"""SGD money type over ``decimal.Decimal``.

Money is serialized as a two-decimal string (e.g. ``"50.00"``).
Floats are rejected at construction time to avoid binary-representation
errors such as ``0.1 + 0.2``.  The same rules apply to mock equity unit
prices.
"""

from __future__ import annotations

import re
from decimal import Decimal, InvalidOperation
from typing import Any

__all__ = ["Money", "MAX_MONEY_SGD"]

#: Hard cap on a single SGD amount in this prototype.
MAX_MONEY_SGD = Decimal("1000000.00")

_STR_RE = re.compile(r"^\d+(\.\d{1,2})?$")


class Money:
    """Immutable SGD money value backed by ``Decimal``.

    Accepts:
        - ``Decimal`` – must have at most 2 fractional digits.
        - ``int`` – normalized to 2 dp.
        - ``str`` – must match ``^\\d+(\\.\\d{1,2})?$``.

    Rejects:
        - ``float`` (including values that arrive via JSON numbers).
        - ``bool`` (which is an ``int`` subclass in Python).
        - ``NaN``, ``Infinity``, negative values.
        - More than 2 fractional digits.
        - Values exceeding :data:`MAX_MONEY_SGD`.
    """

    __slots__ = ("_value",)

    def __init__(self, value: Any, *, _allow_zero: bool = True) -> None:
        """Create a :class:`Money` instance.

        ``_allow_zero`` is a private escape hatch used by the validator
        tests; production code always allows zero as a valid (zero-amount)
        value for non-amount fields.
        """
        if isinstance(value, bool):
            raise TypeError("bool is not a valid money value")

        if isinstance(value, float):
            raise TypeError("float is not a valid money value; use Decimal or str")

        if isinstance(value, Decimal):
            dec = value
        elif isinstance(value, int) and not isinstance(value, bool):
            dec = Decimal(value)
        elif isinstance(value, str):
            if not _STR_RE.match(value):
                raise ValueError(
                    f"money string must match ^\\d+(\\.\\d{{1,2}})?$; got {value!r}"
                )
            dec = Decimal(value)
        elif isinstance(value, Money):
            dec = value._value
        else:
            raise TypeError(f"unsupported type for Money: {type(value).__name__}")

        if not dec.is_finite():
            raise ValueError("money must be finite (not NaN or Infinity)")

        if dec < 0:
            raise ValueError("money must be non-negative")

        # Reject more than 2 fractional digits.
        if dec.as_tuple().exponent < -2:
            raise ValueError(
                f"money must have at most 2 decimal places; got exponent "
                f"{dec.as_tuple().exponent}"
            )

        if dec > MAX_MONEY_SGD:
            raise ValueError(
                f"money {dec} exceeds the prototype cap of {MAX_MONEY_SGD}"
            )

        if not _allow_zero and dec == 0:
            raise ValueError("money must be positive (non-zero)")

        # Normalize to exactly 2 dp.
        object.__setattr__(self, "_value", dec.quantize(Decimal("0.01")))

    # -- properties ---------------------------------------------------------

    @property
    def value(self) -> Decimal:
        """The underlying ``Decimal`` (2 dp)."""
        return self._value

    # -- serialization ------------------------------------------------------

    def to_str(self) -> str:
        """Serialize as a two-decimal string, e.g. ``"50.00"``."""
        return f"{self._value:.2f}"

    def __str__(self) -> str:
        return self.to_str()

    def __repr__(self) -> str:
        return f"Money({self.to_str()!r})"

    # -- comparison / hashing ----------------------------------------------

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self._value == other._value
        if isinstance(other, (Decimal, int)) and not isinstance(other, bool):
            return self._value == Decimal(other)
        return NotImplemented

    def __lt__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self._value < other._value
        if isinstance(other, (Decimal, int)) and not isinstance(other, bool):
            return self._value < Decimal(other)
        return NotImplemented

    def __le__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self._value <= other._value
        if isinstance(other, (Decimal, int)) and not isinstance(other, bool):
            return self._value <= Decimal(other)
        return NotImplemented

    def __gt__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self._value > other._value
        if isinstance(other, (Decimal, int)) and not isinstance(other, bool):
            return self._value > Decimal(other)
        return NotImplemented

    def __ge__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self._value >= other._value
        if isinstance(other, (Decimal, int)) and not isinstance(other, bool):
            return self._value >= Decimal(other)
        return NotImplemented

    def __hash__(self) -> int:
        return hash(self._value)

    # -- arithmetic helpers -------------------------------------------------

    def __add__(self, other: "Money | Decimal | int") -> "Money":
        if isinstance(other, Money):
            other = other._value
        elif isinstance(other, bool):
            raise TypeError("cannot add bool to Money")
        elif not isinstance(other, (Decimal, int)):
            return NotImplemented
        return Money(self._value + Decimal(other))

    def __sub__(self, other: "Money | Decimal | int") -> "Money":
        if isinstance(other, Money):
            other = other._value
        elif isinstance(other, bool):
            raise TypeError("cannot subtract bool from Money")
        elif not isinstance(other, (Decimal, int)):
            return NotImplemented
        return Money(self._value - Decimal(other))

    def __mul__(self, other: "int") -> "Money":
        if isinstance(other, bool) or not isinstance(other, int):
            return NotImplemented
        return Money(self._value * other)

    __rmul__ = __mul__

    @classmethod
    def quantize_down(cls, value: Decimal) -> "Money":
        """Quantize a ``Decimal`` to 2 dp with ``ROUND_DOWN``.

        Used by the :term:`AmountExpr` resolver to floor fractions.
        """
        from decimal import ROUND_DOWN

        return cls(value.quantize(Decimal("0.01"), rounding=ROUND_DOWN))

"""Money type tests."""

from __future__ import annotations

import json
from decimal import Decimal

import pytest
from pydantic import BaseModel, ValidationError

from shared.money import MAX_MONEY_SGD, Money


class _Wrapper(BaseModel):
    """Simple Pydantic model wrapping a Money field for JSON tests."""

    amount: Money

    @classmethod
    def model_validate(cls, obj, **kw):  # type: ignore[override]
        return super().model_validate(obj, **kw)


class TestMoneyAccept:
    def test_accept_int(self) -> None:
        m = Money(50)
        assert m.to_str() == "50.00"

    def test_accept_decimal(self) -> None:
        m = Money(Decimal("15.00"))
        assert m.to_str() == "15.00"

    def test_accept_decimal_int_value(self) -> None:
        m = Money(Decimal("100"))
        assert m.to_str() == "100.00"

    def test_accept_str_no_dp(self) -> None:
        m = Money("50")
        assert m.to_str() == "50.00"

    def test_accept_str_one_dp(self) -> None:
        m = Money("50.5")
        assert m.to_str() == "50.50"

    def test_accept_str_two_dp(self) -> None:
        m = Money("50.50")
        assert m.to_str() == "50.50"

    def test_accept_money_passthrough(self) -> None:
        m1 = Money("10.00")
        m2 = Money(m1)
        assert m2.to_str() == "10.00"


class TestMoneyReject:
    def test_reject_float(self) -> None:
        with pytest.raises(TypeError, match="float"):
            Money(0.1)

    def test_reject_bool(self) -> None:
        with pytest.raises(TypeError, match="bool"):
            Money(True)

    def test_reject_nan(self) -> None:
        with pytest.raises(ValueError, match="finite"):
            Money(Decimal("NaN"))

    def test_reject_infinity(self) -> None:
        with pytest.raises(ValueError, match="finite"):
            Money(Decimal("Infinity"))

    def test_reject_negative_infinity(self) -> None:
        with pytest.raises(ValueError, match="finite"):
            Money(Decimal("-Infinity"))

    def test_reject_more_than_two_dp(self) -> None:
        with pytest.raises(ValueError, match="2 decimal places"):
            Money("1.234")

    def test_reject_negative(self) -> None:
        with pytest.raises(ValueError, match="non-negative"):
            Money("-5.00")

    def test_reject_negative_decimal(self) -> None:
        with pytest.raises(ValueError, match="non-negative"):
            Money(Decimal("-1.00"))

    def test_reject_absurd_size(self) -> None:
        with pytest.raises(ValueError, match="exceeds"):
            Money(MAX_MONEY_SGD + Decimal("0.01"))

    def test_reject_float_from_json(self) -> None:
        """A JSON float must be rejected when it arrives as a Money field."""
        data = '{"amount": 0.1}'
        parsed = json.loads(data)
        with pytest.raises((TypeError, ValidationError)):
            _Wrapper.model_validate(parsed)

    def test_reject_float_01_plus_02_from_json(self) -> None:
        """0.1+0.2 style float must be rejected."""
        data = '{"amount": 0.30000000000000004}'
        parsed = json.loads(data)
        with pytest.raises((TypeError, ValidationError)):
            _Wrapper.model_validate(parsed)

    def test_reject_string_with_more_than_two_dp(self) -> None:
        with pytest.raises(ValueError):
            Money("1.234")

    def test_reject_empty_string(self) -> None:
        with pytest.raises(ValueError):
            Money("")

    def test_reject_none(self) -> None:
        with pytest.raises(TypeError):
            Money(None)  # type: ignore[arg-type]


class TestMoneySerialize:
    def test_serialize_two_decimal_string(self) -> None:
        assert Money("50").to_str() == "50.00"
        assert Money("50.5").to_str() == "50.50"
        assert Money("50.50").to_str() == "50.50"

    def test_str_repr(self) -> None:
        m = Money("50.00")
        assert str(m) == "50.00"
        assert repr(m) == "Money('50.00')"

    def test_equality(self) -> None:
        assert Money("50.00") == Money("50.00")
        assert Money("50.00") == Decimal("50.00")
        assert Money("50.00") != Money("51.00")

    def test_hashable(self) -> None:
        assert hash(Money("50.00")) == hash(Money("50.00"))

"""AmountExpr resolver tests."""

from __future__ import annotations

from decimal import Decimal

import pytest

from shared.money import Money
from shared.schemas import (
    AmountLiteral,
    FractionOfLeg,
    RemainingBalance,
    resolve_amount_exprs,
)


class TestLiteralResolve:
    def test_literal_amount(self) -> None:
        legs = [("leg-1", "acct-a", AmountLiteral(amount=Money("50.00")))]
        result = resolve_amount_exprs(legs, {})
        assert len(result) == 1
        assert result[0].to_str() == "50.00"


class TestFractionOfLeg:
    def test_half_of_preceding_leg(self) -> None:
        legs = [
            ("leg-1", "acct-a", AmountLiteral(amount=Money("100.00"))),
            ("leg-2", "acct-b", FractionOfLeg(leg_id="leg-1", numerator=1, denominator=2)),
        ]
        result = resolve_amount_exprs(legs, {})
        assert result[1].to_str() == "50.00"

    def test_third_rounds_down(self) -> None:
        """1/3 of 100.00 = 33.33 (ROUND_DOWN)."""
        legs = [
            ("leg-1", "acct-a", AmountLiteral(amount=Money("100.00"))),
            ("leg-2", "acct-b", FractionOfLeg(leg_id="leg-1", numerator=1, denominator=3)),
        ]
        result = resolve_amount_exprs(legs, {})
        assert result[1].to_str() == "33.33"

    def test_forward_reference_rejected(self) -> None:
        legs = [
            ("leg-1", "acct-a", FractionOfLeg(leg_id="leg-2", numerator=1, denominator=2)),
            ("leg-2", "acct-b", AmountLiteral(amount=Money("100.00"))),
        ]
        with pytest.raises(ValueError, match="forward|unknown"):
            resolve_amount_exprs(legs, {})

    def test_missing_reference_rejected(self) -> None:
        legs = [
            ("leg-1", "acct-a", FractionOfLeg(leg_id="nonexistent", numerator=1, denominator=2)),
        ]
        with pytest.raises(ValueError, match="forward|unknown"):
            resolve_amount_exprs(legs, {})

    def test_self_reference_rejected(self) -> None:
        legs = [
            ("leg-1", "acct-a", FractionOfLeg(leg_id="leg-1", numerator=1, denominator=2)),
        ]
        with pytest.raises(ValueError, match="self-reference"):
            resolve_amount_exprs(legs, {})

    def test_fraction_gt_one_rejected(self) -> None:
        """numerator > denominator is rejected at the model level."""
        with pytest.raises(Exception, match="fraction"):
            FractionOfLeg(leg_id="leg-1", numerator=3, denominator=2)


class TestRemainingBalance:
    def test_remaining_balance_simple(self) -> None:
        legs = [
            ("leg-1", "acct-a", RemainingBalance(account_id="acct-a")),
        ]
        balances = {"acct-a": Decimal("500.00")}
        result = resolve_amount_exprs(legs, balances)
        assert result[0].to_str() == "500.00"

    def test_remaining_balance_after_preceding_debit(self) -> None:
        """Remaining balance after a preceding leg debited the same account."""
        legs = [
            ("leg-1", "acct-a", AmountLiteral(amount=Money("200.00"))),
            ("leg-2", "acct-a", RemainingBalance(account_id="acct-a")),
        ]
        balances = {"acct-a": Decimal("500.00")}
        result = resolve_amount_exprs(legs, balances)
        assert result[0].to_str() == "200.00"
        assert result[1].to_str() == "300.00"

    def test_remaining_balance_unknown_account_rejected(self) -> None:
        legs = [
            ("leg-1", "acct-a", RemainingBalance(account_id="acct-unknown")),
        ]
        with pytest.raises(ValueError, match="unknown account"):
            resolve_amount_exprs(legs, {"acct-a": Decimal("100.00")})

    def test_remaining_balance_negative_rejected(self) -> None:
        """If debits exceed balance, reject."""
        legs = [
            ("leg-1", "acct-a", AmountLiteral(amount=Money("600.00"))),
            ("leg-2", "acct-a", RemainingBalance(account_id="acct-a")),
        ]
        balances = {"acct-a": Decimal("500.00")}
        with pytest.raises(ValueError, match="negative"):
            resolve_amount_exprs(legs, balances)

